+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * How the customer list is narrowed down: free text matched against names, plus
+ * a set of statuses. Immutable, and cheap to compare, so a caller can tell
+ * whether the filter really changed.
+ *
+ * <p>The name filter is split on whitespace into terms, and a customer matches
+ * only if <em>every</em> term is a substring of its first or last name. Matching
+ * ignores case and accents in both directions: {@code makinen}, {@code MAKINEN}
+ * and {@code mäkinen} all match {@code Mäkinen}. An empty name matches every
+ * customer, and so does an empty set of statuses.
+ *
+ * @param name     the raw name filter, stripped of insignificant whitespace
+ * @param statuses the statuses to show, empty for all of them
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    // Declared last: the constructor below uses the patterns above.
+    private static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter(String name, Set<CustomerStatus> statuses) {
+        this.name = (name == null) ? "" : WHITESPACE.matcher(name.strip()).replaceAll(" ");
+        this.statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                // An EnumSet iterates in declaration order, which is the order
+                // the statuses appear in as a query parameter.
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** The filter that matches every customer. */
+    public static CustomerFilter empty() {
+        return EMPTY;
+    }
+
+    /** Whether this filter narrows anything down at all. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /**
+     * The name filter split into terms, each folded so that comparing it to a
+     * folded name ignores case and accents.
+     */
+    public List<String> nameTerms() {
+        return name.isEmpty() ? List.of() : List.of(WHITESPACE.split(fold(name)));
+    }
+
+    /**
+     * This filter as a predicate. The name terms are folded once, not once per
+     * customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> wanted = statuses;
+        return customer -> (wanted.isEmpty() || wanted.contains(customer.status()))
+                && matchesName(customer, terms);
+    }
+
+    /** Whether one customer passes this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds text for insensitive comparison: decomposes it, drops the combining
+     * marks and lower-cases what is left, so {@code Joséphine} folds to
+     * {@code josephine}.
+     */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
