+
+/**
+ * The same view in a real browser, for the two things Karibu cannot see: what
+ * the address bar says, and what typing costs the backend.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void filterIsWrittenToTheAddressBar() {
+        typeName("vir");
+        waitForUrl(url -> url.endsWith("?name=vir"));
+
+        toggleStatuses("ACTIVE", "CLOSED");
+        waitForUrl(url -> url.endsWith("?name=vir&status=ACTIVE,CLOSED"));
+
+        nameField().clear();
+        waitForUrl(url -> url.endsWith("?status=ACTIVE,CLOSED"));
+
+        toggleStatuses("ACTIVE", "CLOSED"); // toggling them off empties the filter
+        waitForUrl(url -> !url.contains("?"));
+    }
+
+    @Test
+    void filterIsReadFromTheAddressBar() {
+        page.navigate(getUrl() + "/?name=aaltonen&status=ACTIVE,CLOSED");
+        waitForVaadin();
+
+        assertEquals("aaltonen", nameField().inputValue());
+        assertEquals(List.of("ACTIVE", "CLOSED"), selectedStatuses());
+
+        String summary = summary().textContent();
+        assertTrue(summary.matches("Showing \\d+ of 500"), summary);
+        assertTrue(!summary.equals("Showing 0 of 500") && !summary.equals("Showing 500 of 500"), summary);
+        assertTrue(page.locator("vaadin-grid-cell-content").allTextContents().stream()
+                .noneMatch("PENDING"::equals), "A PENDING customer slipped through the filter");
+    }
+
+    /** The list narrows while typing: no Enter, no leaving the field. */
+    @Test
+    void theGridFollowsTheTyping() {
+        waitForVaadin();
+        assertEquals("Showing 500 of 500", summary().textContent());
+
+        nameField().pressSequentially("aaltonen", new Locator.PressSequentiallyOptions().setDelay(30));
+
+        page.waitForCondition(() -> summary().textContent().matches("Showing \\d+ of 500")
+                && !summary().textContent().equals("Showing 500 of 500"));
+        int matching = Integer.parseInt(summary().textContent().replaceAll("\\D+", " ").strip().split(" ")[0]);
+        assertTrue(matching > 0, summary().textContent());
+        page.waitForCondition(() -> gridRowCount() == matching);
+    }
+
+    /** Typing a name is a query or two, and it does not fill the back button. */
+    @Test
